/** Returns the median revenue (units times price) of the rows. */
export function median(rows) {
  const revenues = rows.map((row) => row.units * row.price).sort((a, b) => a - b)
  const middle = Math.floor(revenues.length / 2)
  return revenues.length % 2 ? revenues[middle] : (revenues[middle - 1] + revenues[middle]) / 2
}

